{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to compute the net stage-1 Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a bonus to the stage-1 Q-value of the action chosen in the previous trial to capture perseveration.",
      "params": [
        {
          "name": "rep",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\n        if last_action != -1:\n            stickiness[last_action] = 1.0\n            \n        q1_vals = beta * (q_stage1_net + rep * stickiness)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free Q-value using the stage-2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay for Unchosen Options",
      "description": "Decays the Q-values of unchosen actions at both stages toward zero to capture memory decay over trials.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_action_1] *= (1 - decay_rate)\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] *= (1 - decay_rate)",
      "expressible_in_slots": true
    }
  ]
}
